input.newString:
// Streams the upload straight to storage.
// blobstore-sdk 2.x added putObjectStream(Readable), so we no longer need
// the old whole-file buffering workaround (required by the 1.x Buffer-only
// putObject). Memory use no longer scales with upload size.
async function upload(io, stream) {
  return io.putObjectStream(stream);
}

