input.command:
cd /workspace && node -e '
const { Readable } = require("node:stream");
const { upload } = require("./src/upload.js");
const io = {
  putObject: () => { throw new Error("putObject (buffering path) must not be used"); },
  async putObjectStream(source) { let n = 0; for await (const c of source) n += c.length; return { bytes: n }; },
};
(async () => {
  const src = Readable.from([Buffer.from("hello "), Buffer.from("world")]);
  const res = await upload(io, src);
  console.log("streamed result:", JSON.stringify(res));
})();
'

